// ?d_0088dc30@@YAXXZ
// partial score=0.55 date=2026-09-15
// cl: /DNDEBUG /DWIN32 /D_WINDOWS /MD /EHs-c- /Oy-
// Open-BFME: the dialog procedure for the Exception dialog. The template lives
// at 0x012D4D98 and DebugExceptionhandler::ExceptionFilter runs it through
// DialogBoxIndirectParamA with this body as its procedure. The body fills the
// static text controls from the two shared buffers, splits the crash text into
// the list box, and puts one list-view row per stack frame.

typedef void *RvaHwnd;
typedef int(__stdcall *RvaIsDebuggerPresentFn)(void);

struct _CONTEXT
{
	unsigned char m_beforeEip[0xB8];
	unsigned Eip;
};

struct _EXCEPTION_POINTERS
{
	void *ExceptionRecord;
	_CONTEXT *ContextRecord;
};

// upstream layout: reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source/debug/debug_stack.h
class DebugStackwalk
{
public:
	class Signature
	{
		enum
		{
			MAX_ADDR = 256
		};

		unsigned m_numAddr;
		unsigned m_addr[MAX_ADDR];

	public:
		unsigned Size(void) const { return m_numAddr; }
		unsigned GetAddress(int n) const;
		static void GetSymbol(unsigned addr, char *buf, unsigned bufSize);
	};
};

// upstream layout: reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source/debug/internal_except.h
class DebugExceptionhandler
{
public:
	static const char *GetExceptionType(_EXCEPTION_POINTERS *pointers, char *buffer);
};

struct RvaListColumn
{
	unsigned mask;
	int fmt;
	int cx;
	const char *pszText;
	int cchTextMax;
	int iSubItem;
	int iImage;
	int iOrder;
};

struct RvaListItem
{
	unsigned mask;
	int iItem;
	int iSubItem;
	unsigned state;
	unsigned stateMask;
	const char *pszText;
	int cchTextMax;
	int iImage;
	long lParam;
	int iIndent;
};

extern "C" void _ReadWriteBarrier(void);
#pragma intrinsic(_ReadWriteBarrier)

extern const char g_Rva0107301CEmptyString[];

extern "C"
{
	__declspec(dllimport) void *__stdcall LoadLibraryA(const char *fileName);
	__declspec(dllimport) void *__stdcall GetProcAddress(void *module, const char *procName);
	__declspec(dllimport) int __stdcall EndDialog(RvaHwnd dialog, int result);
	__declspec(dllimport) RvaHwnd __stdcall GetDlgItem(RvaHwnd dialog, int id);
	__declspec(dllimport) int __stdcall ShowWindow(RvaHwnd window, int command);
	__declspec(dllimport) long __stdcall SendDlgItemMessageA(RvaHwnd dialog, int id,
		unsigned message, unsigned wParam, long lParam);
	__declspec(dllimport) long __stdcall SendMessageA(RvaHwnd window, unsigned message,
		unsigned wParam, long lParam);
	__declspec(dllimport) void *__stdcall CreateFontA(int height, int width, int escapement,
		int orientation, int weight, unsigned italic, unsigned underline, unsigned strikeOut,
		unsigned charSet, unsigned outputPrecision, unsigned clipPrecision, unsigned quality,
		unsigned pitchAndFamily, const char *face);
	__declspec(dllimport) char *__cdecl strtok(char *text, const char *delimiters);

	extern char g_Rva01336EB8TextBuffer[256];
	extern char g_Rva01336FB8TextBuffer[1024];
	extern _EXCEPTION_POINTERS *g_Rva013373B8ExceptionPointers;
}

extern DebugStackwalk::Signature g_Rva013373C8StackSignature;

static __forceinline int Rva0088DC30OnInitDialog(RvaHwnd dialog)
{
	void *kernel = LoadLibraryA("kernel32");
	if (kernel != 0)
	{
		RvaIsDebuggerPresentFn probe =
			(RvaIsDebuggerPresentFn)GetProcAddress(kernel, "IsDebuggerPresent");
		if (probe != 0 && probe() == 0)
			ShowWindow(GetDlgItem(dialog, 4), 0);
	}

	SendDlgItemMessageA(dialog, 0x67, 0xC, 0, (long)g_Rva01336EB8TextBuffer);

	char *line = g_Rva01336FB8TextBuffer;
	char *cursor = g_Rva01336FB8TextBuffer;
	char c;
	bool last;
	for (;;)
	{
		c = *cursor;
		if (c == 0 || c == '\n')
		{
			last = (c == 0);
			*cursor = 0;
			SendDlgItemMessageA(dialog, 0x69, 0x180, 0, (long)line);
			if (last)
				break;
			line = cursor + 1;
			cursor = cursor + 1;
		}
		else if (c == '\r')
		{
			*cursor = 0;
			++cursor;
		}
		else
		{
			++cursor;
		}
	}

	SendDlgItemMessageA(dialog, 0x69, 0x30,
		(unsigned)CreateFontA(13, 0, 0, 0, 400, 0, 0, 0, 0, 0, 0, 0, 0x31, 0), 1);

	SendDlgItemMessageA(dialog, 0x64, 0xC, 0,
		(long)DebugExceptionhandler::GetExceptionType(g_Rva013373B8ExceptionPointers,
			g_Rva01336FB8TextBuffer));
	SendDlgItemMessageA(dialog, 0x65, 0xC, 0, (long)g_Rva01336FB8TextBuffer);

	DebugStackwalk::Signature::GetSymbol(g_Rva013373B8ExceptionPointers->ContextRecord->Eip,
		g_Rva01336FB8TextBuffer, 0x400);
	SendDlgItemMessageA(dialog, 0x66, 0xC, 0, (long)g_Rva01336FB8TextBuffer);

	RvaHwnd list = GetDlgItem(dialog, 0x68);

	RvaListColumn column;
	RvaListItem item;
	column.pszText = g_Rva0107301CEmptyString;
	if (g_Rva013373C8StackSignature.Size() == 0)
	{
		column.mask = 6;
		column.cx = 0x2B2;
		SendMessageA(list, 0x101B, 0, (long)&column);

		item.iItem = 0;
		item.iSubItem = 0;
		item.mask = 1;
		item.pszText = "No stack data available - check for dbghelp.dll";
		SendMessageA(list, 0x1007, 0, (long)&item);
		return 1;
	}

	column.mask = 6;
	column.cx = 0;
	SendMessageA(list, 0x101B, 0, (long)&column);

	column.mask = 7;
	column.pszText = "Address";
	column.cx = 0x3C;
	column.fmt = 1;
	SendMessageA(list, 0x101B, 1, (long)&column);

	column.mask = 6;
	column.pszText = "Module";
	column.cx = 0x78;
	SendMessageA(list, 0x101B, 2, (long)&column);

	column.pszText = "Symbol";
	column.cx = 0x12C;
	SendMessageA(list, 0x101B, 3, (long)&column);

	column.pszText = "File";
	column.cx = 0x82;
	SendMessageA(list, 0x101B, 4, (long)&column);

	column.pszText = "Line";
	column.cx = 0x50;
	SendMessageA(list, 0x101B, 5, (long)&column);

	for (unsigned frame = 0; frame < g_Rva013373C8StackSignature.Size(); ++frame)
	{
		DebugStackwalk::Signature::GetSymbol(
			g_Rva013373C8StackSignature.GetAddress(frame), g_Rva01336FB8TextBuffer, 0x400);

		item.iItem = frame;
		item.iSubItem = 0;
		item.mask = 0;
		int row = (int)SendMessageA(list, 0x1007, 0, (long)&item);

		item.iItem = row;
		item.mask = 1;
		item.iSubItem = 1;
		item.pszText = strtok(g_Rva01336FB8TextBuffer, " ");
		SendMessageA(list, 0x1006, 0, (long)&item);

		item.iSubItem = 2;
		item.pszText = strtok(0, ",");
		SendMessageA(list, 0x1006, 0, (long)&item);

		item.iSubItem = 3;
		item.pszText = strtok(0, ",");
		SendMessageA(list, 0x1006, 0, (long)&item);

		item.iSubItem = 4;
		item.pszText = strtok(0, ":");
		SendMessageA(list, 0x1006, 0, (long)&item);

		item.iSubItem = 5;
		item.pszText = strtok(0, g_Rva0107301CEmptyString);
		SendMessageA(list, 0x1006, 0, (long)&item);
	}

	return 1;
}

int __stdcall Rva0088DC30ExceptionDialogProc(RvaHwnd dialog, unsigned message,
	unsigned wParam, long)
{
	switch (message)
	{
	case 0x110:
		return Rva0088DC30OnInitDialog(dialog);

	case 0x111:
		if ((unsigned short)wParam == 1 || (unsigned short)wParam == 4)
			EndDialog(dialog, (unsigned short)wParam);
		return 0;
	}

	return 0;
}
